import { expect, mock, test } from "bun:test";
const cache = new Map<string, string>();
mock.module("@/lib/localforage-storage", () => ({ localForageStorage: { getItem: async (key: string) => cache.get(key) || null, setItem: async (key: string, value: string) => { cache.set(key, value); }, removeItem: async (key: string) => { cache.delete(key); } } }));
mock.module("@/services/image-storage", () => ({ previewUrlFor: () => undefined, ensureImagePreview: async () => {}, resolveImageUrl: async (_key: string, url: string) => url, uploadImage: async (url: string) => ({ url }), collectImageStorageKeys: () => [], getImageBlob: async () => null, setImageBlob: async () => {}, cleanupUnusedImages: async () => {} }));
mock.module("@/services/file-storage", () => ({ resolveMediaUrl: async (_key: string, url: string) => url, getMediaBlob: async () => null, setMediaBlob: async () => {}, cleanupUnusedMedia: async () => {} }));
mock.module("@/services/workbench/projects", () => ({ durableDocument: async (value: unknown) => JSON.parse(JSON.stringify(value)) }));
let exported: Blob;
mock.module("file-saver", () => ({ saveAs: (blob: Blob) => { exported = blob; } }));
const { useAssetStore } = await import("@/stores/use-asset-store");
const { useWorkbenchStore } = await import("@/stores/use-workbench-store");
const { assetInFolder, validateAssetFolders } = await import("@/lib/asset-folders");
const { exportAssets, readAssetPackage } = await import("@/pages/assets/asset-transfer");
const { createZip } = await import("@/lib/zip");
const store = () => useAssetStore.getState();
const asset = { id: "original", kind: "text" as const, title: "Keep", coverUrl: "", tags: [], data: { content: "Untouched content" }, createdAt: "a", updatedAt: "a" };
const folder = { id: "remote-folder", kind: "folder" as const, title: "Cloud folder", data: {}, createdAt: "a", updatedAt: "a" };
const version = Number(process.env.LIBRARY_TEST_VERSION);
const integrated = process.env.VITE_APP_MODE !== "standalone";
const records = new Map<string, any>(version === 2 ? [["envelope-folder", { id: "envelope-folder", revision: 4, document: folder }], ["envelope-asset", { id: "envelope-asset", revision: 7, document: { ...asset, folderId: folder.id } }]] : [["envelope-asset", { id: "envelope-asset", revision: 7, document: asset }]]);
const calls: any[] = [];
let conflict = false;
mock.module("@/services/api/workbench", () => ({ workbenchRequest: async (path: string, init: RequestInit = {}) => {
    expect(new Headers(init.headers).get("X-Canvas-Library-Version")).toBe("2");
    const method = init.method || "GET", body = init.body ? JSON.parse(String(init.body)) : {};
    calls.push({ path, method, body });
    if (method === "GET") return { items: [...records.values()], ...(version === 2 ? { libraryVersion: 2 } : {}) };
    if (conflict) throw new Error("Revision conflict");
    const id = method === "POST" ? `server-${body.document.id}` : decodeURIComponent(path.split("/").at(-1)!);
    const current = records.get(id);
    if (current) expect(body.revision).toBe(current.revision);
    if (method === "DELETE") { records.delete(id); return { ok: true }; }
    if (body.document.folderId) expect([...records.values()].some(item => item.document.kind === "folder" && item.document.id === body.document.folderId)).toBe(true);
    const result = { id, revision: (current?.revision || 0) + 1, document: body.document };
    records.set(id, result); return result;
} }));

test("folder deletion preserves assets; batch move, legacy local cache and ZIP remap stay lossless", async () => {
    useWorkbenchStore.setState({ libraryVersion: 2 });
    useAssetStore.setState({ assets: [asset], folders: [] });
    for (const invalid of [{ ...folder, parentId: "nested" }, { ...folder, folderId: "nested" }, { ...folder, data: { nested: true } }]) expect(() => validateAssetFolders([invalid])).toThrow("Invalid asset folders");
    const first = store().addFolder(" First "), empty = store().addFolder("Empty");
    store().renameFolder(first, "Renamed");
    store().moveAssets([asset.id], first);
    expect(assetInFolder(store().assets[0], first, store().folders)).toBe(true);
    const originalData = store().assets[0].data;
    await exportAssets(store().assets, "test.zip", store().folders);
    const imported = await readAssetPackage(new File([exported!], "test.zip"));
    expect(imported.folders.map(f => f.title)).toEqual(["Renamed", "Empty"]);
    store().importAssets(imported.assets, imported.folders);
    expect(store().assets).toHaveLength(2);
    const copy = store().assets.find(a => a.id !== asset.id)!;
    expect(copy.folderId).not.toBe(first);
    expect(store().folders.some(f => f.id === copy.folderId && f.title === "Renamed")).toBe(true);
    expect(store().folders.filter(f => f.title === "Empty")).toHaveLength(2);
    store().moveAssets(store().assets.map(a => a.id), first);
    store().removeFolder(first);
    expect(store().assets).toHaveLength(2);
    expect(store().assets.every(a => assetInFolder(a, "", store().folders))).toBe(true);
    expect(store().assets.find(a => a.id === asset.id)!.data).toBe(originalData);
    expect(store().folders.some(f => f.id === empty)).toBe(true);
    const legacyZip = await createZip([{ name: "assets.json", data: JSON.stringify({ app: "infinite-canvas", version: 1, assets: [asset], files: [] }) }]);
    const legacy = await readAssetPackage(new File([legacyZip], "old.zip"));
    expect(legacy.folders).toEqual([]);
    store().importAssets(legacy.assets, legacy.folders);
    expect(store().assets[0].folderId).toBeUndefined();
    const destination = store().addFolder("Import here");
    const existingFolders = store().folders;
    const originalPackage = JSON.stringify(imported);
    const existingAssets = store().assets;
    store().importAssets([...imported.assets, asset], imported.folders, destination);
    expect(store().folders).toEqual(existingFolders);
    expect(store().assets.slice(0, imported.assets.length + 1).every(a => a.folderId === destination)).toBe(true);
    expect(store().assets.slice(imported.assets.length + 1)).toEqual(existingAssets);
    expect(JSON.stringify(imported)).toBe(originalPackage);
    expect(() => store().importAssets([asset], [], "deleted-folder")).toThrow("Folder not found");
    cache.set("infinite-canvas:asset_store", JSON.stringify({ state: { assets: [asset] }, version: 0 }));
    await useAssetStore.persist.rehydrate();
    expect(store().folders).toEqual([]);
    expect(store().assets).toEqual([asset]);
});

if (integrated) test("version handshake, cloud restore, save order, delete and conflict recovery", async () => {
    useAssetStore.setState({ assets: [], folders: [] }); cache.clear();
    useWorkbenchStore.setState({ libraryVersion: 0 });
    expect(() => store().addFolder("Before handshake")).toThrow("version 2");
    const library = await import("@/services/workbench/library");
    await library.initializeCloudLibrary();
    expect(store().assets[0].data).toEqual(asset.data);
    if (version !== 2) {
        expect(store().folders).toEqual([]);
        expect(useWorkbenchStore.getState().libraryVersion).toBe(0);
        expect(() => store().addFolder("Blocked")).toThrow("version 2");
        store().updateAsset(asset.id, { title: "Legacy still editable" });
        await library.saveCloudLibrary();
        expect(records.get("envelope-asset").document.title).toBe("Legacy still editable");
        return;
    }
    expect(store().folders).toEqual([folder]);
    expect(store().assets[0].folderId).toBe(folder.id);
    const target = store().addFolder("Destination");
    store().moveAssets([asset.id], target);
    await library.saveCloudLibrary();
    const create = calls.findIndex(c => c.method === "POST" && c.body.document.id === target);
    const move = calls.findIndex(c => c.method === "PUT" && c.body.document.folderId === target);
    expect(create).toBeLessThan(move);
    expect(records.get("envelope-asset").document.id).toBe(asset.id);
    const deleteStart = calls.length;
    store().removeFolder(target); await library.saveCloudLibrary();
    const deletionCalls = calls.slice(deleteStart);
    expect(deletionCalls.findIndex(c => c.method === "PUT" && c.body.document.id === asset.id)).toBeLessThan(deletionCalls.findIndex(c => c.method === "DELETE" && c.path.endsWith(target)));
    expect(records.get("envelope-asset").document.folderId).toBeUndefined();
    expect([...records.values()].some(item => item.document.id === target)).toBe(false);
    expect(records.has("envelope-asset")).toBe(true);
    conflict = true;
    store().renameFolder(folder.id, "Unsaved folder rename");
    await expect(library.saveCloudLibrary()).rejects.toThrow("Revision conflict");
    expect(cache.get("workbench:library-recovery:v1")).toContain("Unsaved folder rename");
    expect(records.get("envelope-folder").document.title).toBe("Cloud folder");
});
